-- DK class stats for levels 1-60, aligned to Warrior/Paladin baselines
-- BaseHP is avg(Warrior, Paladin) * 1.03
-- Stamina is avg(Warrior, Paladin) * 1.04
-- Strength/Agility/Intellect/Spirit are straight averages
-- BaseMana stays 0 (runic power class)

DELETE FROM `player_class_stats` WHERE `Class` = 6 AND `Level` BETWEEN 1 AND 60;

